import ast
import json
import re
import resource
import subprocess
import sys


def check_fibonacci(content):
    blocks=re.findall(r'```(?:python)?\s*\n(.*?)```',content,re.S)
    source='\n'.join(blocks) if blocks else content
    proc=subprocess.run([sys.executable,__file__],input=source,text=True,capture_output=True,timeout=5)
    return {'passed':proc.returncode==0,'checks':[0,1,2,7,10,20], 'error':proc.stderr[-1000:] if proc.returncode else None}

if __name__=='__main__':
    resource.setrlimit(resource.RLIMIT_CPU,(2,2))
    source=sys.stdin.read()
    tree=ast.parse(source)
    names={node.name for node in tree.body if isinstance(node,ast.FunctionDef)}
    allowed={'range':range,'len':len,'int':int,'list':list,'isinstance':isinstance,'ValueError':ValueError,'TypeError':TypeError,'print':print}
    for node in ast.walk(tree):
        if isinstance(node,(ast.Import,ast.ImportFrom,ast.ClassDef)):raise ValueError('unneeded import or class in Fibonacci probe')
        if isinstance(node,ast.Name) and node.id.startswith('__'):raise ValueError('private name')
        if isinstance(node,ast.Attribute) and node.attr not in ('append','extend'):raise ValueError('unneeded attribute')
        if isinstance(node,ast.Call) and isinstance(node.func,ast.Name) and node.func.id not in names|allowed.keys():raise ValueError('unneeded call')
    scope={'__builtins__':allowed}
    exec(compile(tree,'<fibonacci-probe>','exec'),scope)
    for n in (0,1,2,7,10,20):
        expected=[];a,b=0,1
        for _ in range(n):expected.append(a);a,b=b,a+b
        assert scope['fibonacci'](n)==expected,(n,scope['fibonacci'](n),expected)

