import asyncio,hashlib,json,os,re,signal,sys,time
from pathlib import Path
import httpx
ROOT=Path('/tmp/glm53-opt-20260909')
def counters(text):
 out={}
 for line in text.splitlines():
  if line.startswith('#'):continue
  parts=line.rsplit(' ',1)
  if len(parts)==2:
   try:out[parts[0]]=float(parts[1])
   except ValueError:pass
 return out
async def metric(client):return counters((await client.get('/metrics')).text)
def total(delta,name):return sum(v for k,v in delta.items() if k.split('{')[0]=='vllm:'+name)
async def check(client,case):
 public='This archival record contains neutral background information.\n'*2000
 unit='This private archival record contains neutral background information.\n'
 salt=f'glm53-aligned-{case}-{time.time_ns()}'
 template={'reasoning_effort':'low','clear_thinking':True}
 def body(key,suffix,lines):
  prompt=public+f'\nThe private vault key for this record is {key}. Remember these exact six digits.\n'+unit*lines+suffix
  return {'model':'local','messages':[{'role':'user','content':prompt}],'temperature':0,'seed':42,'max_tokens':128,'chat_template_kwargs':template,'cache_salt':salt}
 count_body=body('684901','',0)
 r=await client.post('/tokenize',json={'model':'local','messages':count_body['messages'],'chat_template_kwargs':template});r.raise_for_status();key_end=r.json()['count']
 (ROOT/f'{case}-aligned_private_probe.py').write_bytes(Path(__file__).read_bytes())
 result={'case':case,'harness_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'started_at':time.time(),'key_end_tokens':key_end,'prime_tail_lines':1750,'query_tail_lines':1750,'cache_salt':salt,'checks':[]}
 path=ROOT/f'{case}-aligned-private.json'
 for attempt in range(4):
  for key in ('684901','684902'):
   r=await client.post('/v1/chat/completions',json=body(key,'\nAcknowledge the record with OK.',1750));r.raise_for_status()
  before=await metric(client)
  async def one(key):
   r=await client.post('/v1/chat/completions',json=body(key,'\nWhat is the private vault key for this record? Return only its six digits.',1750));r.raise_for_status();x=r.json();content=x['choices'][0]['message'].get('content') or ''
   return {'key':key,'correct':set(re.findall(r'(?<!\d)\d{6}(?!\d)',content))=={key},'response':x}
  rows=await asyncio.gather(*(one(key) for key in ('684901','684902')))
  after=await metric(client);delta={k:v-before.get(k,0) for k,v in after.items()}
  hits=total(delta,'prefix_cache_hits_total');queries=total(delta,'prefix_cache_queries_total');maximum=max(row['response']['usage']['prompt_tokens'] for row in rows)
  row={'attempt':attempt,'prefix_hits':hits,'prefix_queries':queries,'max_prompt_tokens':maximum,'key_end_tokens':key_end,'min_hits_lower_bound':hits-maximum,'both_keys_cached':hits-maximum>key_end,'correct':sum(x['correct'] for x in rows),'rows':rows}
  result['checks'].append(row);path.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
  print('ALIGNED_PRIVATE',json.dumps({k:v for k,v in row.items() if k!='rows'}),flush=True)
 result['finished_at']=time.time();result['passed']=all(r['correct']==2 and r['both_keys_cached'] for r in result['checks']);path.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
 return result
async def main():
 case=sys.argv[1]
 if '--wait-evaluation' in sys.argv:
  deadline=time.monotonic()+600
  while True:
   x=json.loads((ROOT/f'{case}-results.json').read_text())
   if 'finished_at' in x or 'diagnostics_finished_at' in x:break
   if time.monotonic()>deadline:raise TimeoutError('original evaluation still active')
   await asyncio.sleep(2)
 async with httpx.AsyncClient(base_url='http://127.0.0.1:8001',timeout=600) as client:result=await check(client,case)
 if not result['passed']:raise AssertionError('aligned private-cache validation failed')
if __name__=='__main__':
 try:asyncio.run(main())
 finally:
  if '--release-hold' in sys.argv:
   marker=ROOT/f'{sys.argv[1]}-hold.json'
   if marker.exists():
    pid=json.loads(marker.read_text())['pid']
    try:
     if f'run_case.py\x00{sys.argv[1]}\x00'.encode() in Path(f'/proc/{pid}/cmdline').read_bytes():os.kill(pid,signal.SIGCONT)
    except FileNotFoundError:pass
    marker.unlink(missing_ok=True)

