import asyncio,hashlib,json,os,re,signal,sys,time
from pathlib import Path
import httpx
root=Path('/tmp/glm53-opt-20260909');case=sys.argv[1]
result={'case':case,'started_at':time.time(),'rows':[],'prompts':{},'harness_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}
output=root/f'{case}-long-context.json'
(root/f'{case}-long_context_bench.py').write_bytes(Path(__file__).read_bytes())
def save():output.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
def count_metrics(text):
 out={}
 for line in text.splitlines():
  if line.startswith('#'):continue
  parts=line.rsplit(' ',1)
  if len(parts)==2:
   try:out[parts[0]]=float(parts[1])
   except ValueError:pass
 return out
async def metric(client):return count_metrics((await client.get('/metrics')).text)
def total(delta,term):return sum(v for k,v in delta.items() if k.split('{')[0]==f'vllm:{term}')
async def run():
 # Wait for the existing evaluator to finish before sending timed requests.
 deadline=time.monotonic()+600
 while '--standalone' not in sys.argv:
  x=json.loads((root/f'{case}-results.json').read_text())
  if 'finished_at' in x or 'diagnostics_finished_at' in x:break
  if time.monotonic()>deadline:raise TimeoutError('original evaluation still active')
  await asyncio.sleep(2)
 async with httpx.AsyncClient(base_url='http://127.0.0.1:8001',timeout=600) as client:
  from aligned_private_probe import check
  aligned=await check(client,case)
  result['aligned_private_probe_passed']=aligned['passed']
  await asyncio.sleep(2)
  line='Archived record. This neutral note contains background information.\n'
  suffix='\nIgnore the archival notes above. Implement a complete Python recursive descent parser for arithmetic expressions with parentheses, unary minus, and precedence. Include tokenization, error reporting, and unit tests. Output code directly.'
  template={'reasoning_effort':'low','clear_thinking':True}
  for trial in range(4):
   for target in (2048,8192,16384):
    prefix=f'Benchmark archive trial {trial}, requested length {target}.\n'
    def prompt(n):return prefix+line*n+suffix
    lo,hi=0,4096
    while lo<hi:
     mid=(lo+hi)//2
     r=await client.post('/tokenize',json={'model':'local','messages':[{'role':'user','content':prompt(mid)}],'chat_template_kwargs':template});r.raise_for_status()
     if r.json()['count']<target:lo=mid+1
     else:hi=mid
    text=prompt(lo);result['prompts'][f'{target}-{trial}']=text
    body={'cache_salt':f'glm53-long-{case}-{result["started_at"]}-{target}-{trial}','model':'local','messages':[{'role':'user','content':text}],'temperature':0,'seed':42,'max_tokens':512,'ignore_eos':True,'chat_template_kwargs':template,'stream':True,'stream_options':{'include_usage':True,'continuous_usage_stats':True}}
    before=await metric(client);begin=time.monotonic();first=None;first_count=None;usage=None;chunks=[]
    async with client.stream('POST','/v1/chat/completions',json=body) as r:
     r.raise_for_status()
     async for line_data in r.aiter_lines():
      if not line_data.startswith('data: ') or line_data=='data: [DONE]':continue
      item=json.loads(line_data[6:]);chunks.append(item)
      if item.get('usage'):usage=item['usage']
      if first is None and any(any(c.get('delta',{}).get(k) for k in ('content','reasoning','reasoning_content')) for c in item.get('choices',[])):
       first=time.monotonic();first_count=item.get('usage',{}).get('completion_tokens')
    end=time.monotonic();assert first is not None and usage['completion_tokens']==512
    after=await metric(client);delta={k:v-before.get(k,0) for k,v in after.items()}
    drafts=total(delta,'spec_decode_num_drafts_total');proposed=total(delta,'spec_decode_num_draft_tokens_total');accepted=total(delta,'spec_decode_num_accepted_tokens_total')
    row={'target_prompt_tokens':target,'trial':trial,'usage':usage,'ttft_s':first-begin,'elapsed_s':end-begin,'decode_tps':511/(end-first),'first_visible_completion_tokens':first_count,'corrected_decode_tps':(512-first_count)/(end-first) if first_count is not None else None,'drafts':drafts,'draft_tokens':proposed,'accepted_tokens':accepted,'acceptance_rate':accepted/proposed if proposed else None,'approx_cycle_ms':(end-first)*1000/drafts if drafts else None,'prefix_hits':total(delta,'prefix_cache_hits_total'),'prompt_sha256':hashlib.sha256(text.encode()).hexdigest()}
    assert row['prefix_hits']==0, 'long prefill benchmark unexpectedly reused prefix cache'
    result['rows'].append(row);save();(root/f'{case}-long-{target}-{trial}-stream.json').write_text(json.dumps(chunks,ensure_ascii=False))
    print(json.dumps(row),flush=True)
 result['finished_at']=time.time();save()
 if not aligned['passed']:raise AssertionError('aligned cache coverage failed; long timings retained')
try:asyncio.run(run())
finally:
 marker=root/f'{case}-hold.json'
 if marker.exists():
  pid=json.loads(marker.read_text())['pid']
  try:
   if f'run_case.py\x00{case}\x00'.encode() in Path(f'/proc/{pid}/cmdline').read_bytes():os.kill(pid,signal.SIGCONT)
  except FileNotFoundError:pass
  marker.unlink(missing_ok=True)
